M.append(dict(id="3.5", go=3, slug="monitoring-and-early-warning", title="Real-time monitoring and early warning", minutes=45, tag="Operations", systems=["data", "risk"],
 summary="Control rooms turn camera and sensor data into density, flow and crowd-pressure maps, and act on thresholds before conditions become critical. Warning levels must be tested and tied to actions.",
 outcomes=["compute density and crowd-pressure maps from video-derived data", "design warning and action levels tied to specific responses", "explain lead time and why early indicators matter", "describe how forecasts and digital twins support decisions"],
 narration_en="The best time to stop a crush is long before it happens. Control rooms at large events watch cameras and sensors and look for signs that density is rising towards critical levels. Video analysis can turn camera images into maps of density and local velocity. From these, crowd pressure, the local density times the variance of velocity, highlights places where a dense crowd has begun to move irregularly, which in the Jamarat data came before falls. A monitoring system needs levels: a watch level, at which staff look more closely, and an action level, at which a predefined response begins, such as stopping inflow, opening a relief route or making an announcement. Each level must be tied to an action and a person with the authority to take it. Lead time matters: a warning is only useful if there is time to act. Short-term forecasts, from models fed by live counts, and so-called digital twins of the venue can extend that lead time. In this module you will build a crowd-pressure map and set warning levels on it.",
 narration_ar="أفضل وقت لمنع التزاحم القاتل هو قبل حدوثه بوقت طويل. تراقب غرف التحكم في الفعاليات الكبيرة الكاميرات وأجهزة الاستشعار وتبحث عن علامات ارتفاع الكثافة نحو المستويات الحرجة. ويمكن لتحليل الفيديو أن يحوّل صور الكاميرات إلى خرائط للكثافة والسرعة المحلية. ومن هذه الخرائط يُبرز ضغط الحشد، أي الكثافة المحلية مضروبة في تباين السرعة، الأماكن التي بدأ فيها حشد كثيف يتحرك بشكل غير منتظم، وهو ما سبق السقوط في بيانات الجمرات. ويحتاج نظام المراقبة إلى مستويات: مستوى مراقبة ينظر عنده الموظفون عن كثب، ومستوى تدخل تبدأ عنده استجابة محددة مسبقاً، كإيقاف التدفق الداخل، أو فتح طريق بديل، أو بث إعلان. ويجب ربط كل مستوى بإجراء وبشخص يملك صلاحية اتخاذه. والمهلة الزمنية مهمة: فالإنذار لا يفيد إلا إذا كان هناك وقت للتصرف. ويمكن للتنبؤات قصيرة المدى، من نماذج تغذيها أعداد حية، ولما يسمى التوائم الرقمية للمكان، أن تمدّ هذه المهلة. ستبني في هذه الوحدة خريطة لضغط الحشد وتضع عليها مستويات إنذار.",
 diagram=dict(title="From cameras to decisions", caption="Measurements feed indicators; indicators cross levels; each level triggers a defined action by someone with authority.",
   nodes=[N("cam", "Cameras and sensors", "CCTV, counters, phones", 120, 110, "data", "Fixed cameras, gate counters, phone data. Coverage of critical points (bottlenecks, junctions, ramps) matters most."),
          N("est", "Estimation", "density and velocity maps", 120, 300, "data", "Density from counting networks; velocity from optical flow or tracking, per cell and per second."),
          N("ind", "Indicators", "density, flow, pressure", 440, 200, "risk", "Local density, flow against capacity, crowd pressure ρ·Var(V), queue growth, counterflow."),
          N("lev", "Levels", "watch, act", 440, 400, "manage", "Thresholds set in advance from data and guidance; tested in exercises; adjusted for the site."),
          N("act", "Actions", "stop inflow, relieve, inform", 760, 400, "manage", "Predefined responses: hold or meter inflow, open relief routes, announcements, deploy stewards."),
          N("fc", "Forecasts", "minutes ahead", 760, 200, "model", "Models fed by live counts forecast density 10–30 minutes ahead, extending lead time; a 'digital twin' keeps model and site in step."),
          N("auth", "Authority", "who decides", 760, 60, "people", "Clear roles: who can stop inflow or close a gate, without waiting for approval up a long chain.")],
   edges=[E("cam", "est"), E("est", "ind"), E("ind", "lev", "crosses"), E("lev", "act", "triggers"), E("ind", "fc", "feeds"), E("fc", "lev", "earlier"), E("auth", "act", "empowers", "people")],
   tour=[T(["cam", "est"], "Cameras and sensors give data; estimation turns it into density and velocity maps.", [["cam", "est"]]),
         T(["ind"], "Indicators summarise risk: density, flow, crowd pressure.", [["est", "ind"]]),
         T(["lev", "act"], "When an indicator crosses a level, a predefined action starts.", [["ind", "lev"], ["lev", "act"]]),
         T(["fc"], "Forecasts give warnings earlier, extending lead time.", [["ind", "fc"], ["fc", "lev"]]),
         T(["auth"], "Someone must have the authority to act at once.", [["auth", "act"]])]),
 sections=[
  S("From video to maps", "<p>Split the scene into cells of about 1 m². In each cell and time window, estimate <b>density</b> (from a counting network or tracking) and <b>local velocity</b> (from optical flow or tracks). Then compute indicators per cell:</p><div class=\"eq\">P<sub>cell</sub> = ρ<sub>cell</sub> × Var(V<sub>cell</sub>) over the last few seconds</div><p>Smooth over time to avoid false alarms from single frames.</p>",
    ("Maps", "data", "Density and velocity per cell.", [("1 m² cells", "Local, not averages."), ("Optical flow", "Velocity from video."), ("Smooth in time", "Avoid false alarms.")])),
  S("Levels tied to actions", "<p>A useful scheme has at least two levels: <b>watch</b> (look closely, prepare) and <b>act</b> (start the predefined response). In the lab, with a watch level of 0.01 and an action level of 0.02 per s², a synthetic dense zone near a bottleneck reaches 0.066, with 20 of 240 cells above the action level. Thresholds must be set from data and guidance for the site, tested in exercises, and reviewed after events. A level without an action, or an action without someone authorised to take it, is useless.</p>",
    ("Levels", "manage", "Watch, act, and who acts.", [("Watch and act", "Two levels at least."), ("Lab: 0.066 per s²", "20 cells above action."), ("Authority", "Someone must decide.")])),
  S("Lead time and forecasts", "<p>At Jamarat in 2006, stop-and-go began about 30 minutes, and turbulence about 10 minutes, before the first deaths (Helbing et al. 2007, as reported in the press). That is the window for action. Short-term forecasts extend it: a macroscopic or network model fed with live gate counts can predict density on a route 10 to 30 minutes ahead. A <b>digital twin</b> is such a model kept continuously in step with the site.</p>",
    ("Lead time", "model", "Warn early enough to act.", [("Stop-and-go ~30 min before", "Jamarat 2006."), ("Forecast 10–30 min", "From live counts."), ("Digital twin", "Model in step with the site.")])),
  S("Pitfalls", "<p><b>False alarms</b> erode trust; <b>missed alarms</b> cost lives. Camera coverage is never complete. Density estimates degrade in very dense crowds, at night and in rain. Operators can be overloaded with screens. At Itaewon, emergency calls warned of danger hours before the crush, but no effective action followed: monitoring only works when it is tied to response.</p>",
    ("Pitfalls", "risk", "Alarms, coverage, overload, response.", [("False vs missed alarms", "Balance them."), ("Coverage gaps", "Critical points first."), ("Itaewon", "Warnings without response.")])),
 ],
 callouts=[C(1, "try", "Explore it", "<p>In the explorer, keep density at 7 per m² and lower the irregular motion. When does the alert switch off?</p>"),
           C(3, "research", "Open question", "<p>How to set and validate warning thresholds across different sites and cameras is an open research problem.</p>")],
 explorer=dict(widget="pressure", intro="A synthetic camera view in 1 m² cells: set the density and irregular motion of the dense zone, and the warning level.", predict="Can a crowd at 7 per m² stay below the warning level?"),
 code=[dict(title="Crowd-pressure map with alert levels", lang="python", file="labs/go3/m35_pressure.py", runnable=True, explain="Builds synthetic density and velocity fields over 50 frames, computes P = ρ·Var(V) per cell, and applies two levels.", expected="max pressure 0.066 per s2 in cell (np.int64(14), np.int64(6))\ncells above warning (0.01): 28, above action (0.02): 20 of 240\nalert: ACT")],
 takeaways=["Turn video into density and velocity maps per cell, smoothed in time.", "Indicators such as crowd pressure cross predefined watch and action levels.", "Each level needs a defined action and someone with authority to take it.", "Forecasts and digital twins extend lead time; monitoring without response fails."],
 quiz=[Q("Crowd pressure is high when…", ["Density is high and motion is orderly", "Density is high and motion is irregular", "Density is low", "People stand still in a line"], 1, "Both dense and irregular."),
       Q("A warning level is useful only if…", ["It is very low", "It triggers a defined action by someone authorised", "It is secret", "It never fires"], 1, "Tie levels to actions."),
       Q("What extends lead time?", ["Bigger screens", "Short-term forecasts from live counts", "More barriers", "Later announcements"], 1, "Forecasts warn earlier."),
       Q("A digital twin is…", ["A copy of the stadium", "A model kept continuously in step with the live site", "A second control room", "A crowd counting camera"], 1, "Model and site in step.")],
 glossary=[G("Optical flow", "A computer-vision estimate of motion between video frames."), G("Watch level", "A threshold at which operators increase attention and prepare."), G("Action level", "A threshold that triggers a predefined response."), G("Lead time", "Time between a warning and the onset of danger."), G("Digital twin", "A model of a site kept continuously updated with live data.")],
 resources=[RS("Helbing, Johansson and Al-Abideen (2007)", "https://arxiv.org/abs/physics/0701203", "Crowd pressure and warning indicators."),
            RS("Johansson et al. (2008): From crowd dynamics to crowd safety", "https://arxiv.org/abs/0810.4590", "Video-based monitoring at the Jamarat."),
            RS("HSE: Managing crowds safely", "https://www.hse.gov.uk/pubns/books/hsg154.htm", "Monitoring, communication and contingency plans.")],
 palace=("Control tent", "Inside the control tent, a wall of screens glows green except one cell turning red; a big lever marked ACT is within reach of a steward wearing a sash that says AUTHORISED, and a clock on the wall shows 30 minutes to spare."),
 qb=[("Recall", "Give the formula for crowd pressure in a cell.", "P = local density × variance of local velocity over a short time window.", "Dense and irregular.", "Pressure needs both packing and shaking."),
     ("Explain", "Why tie warning levels to predefined actions?", "Because a warning without a planned response and an authorised decision maker leads to delay; predefined actions can start immediately.", "Decide in advance what you will do.", "A fire alarm that also unlocks the doors."),
     ("Explain", "What is lead time and why does it matter?", "The time between a warning and danger; only warnings with enough lead time allow inflow to be stopped and crowds relieved.", "Late warnings cannot help.", "A weather warning after the storm."),
     ("Calculate", "A cell has density 6 per m² and speed variance 0.004 m²/s². Pressure?", "6 × 0.004 = 0.024 per s², above a 0.02 action level.", "Multiply density by variance.", "Six people shaking a little each."),
     ("Apply", "Name two pitfalls of camera-based monitoring.", "Incomplete coverage, poor estimates in very dense crowds or bad light, false alarms eroding trust, operator overload, and warnings without response.", "Technology needs organisation.", "A smoke detector nobody listens to."),
     ("Explain", "How can forecasts help a control room?", "Models fed by live counts can predict density 10–30 minutes ahead, so staff can act before thresholds are reached.", "See around the corner.", "A satnav warning of traffic ahead.")]))
M.append(dict(id="3.6", go=3, slug="simulating-a-mass-gathering", title="Simulating a mass gathering", minutes=50, tag="Methods", systems=["data", "space"],
 summary="Build the geometry, set demand and schedules, choose and calibrate a model, run many seeds and scenarios, and analyse sensitivity. Open simulators such as JuPedSim make this reproducible.",
 outcomes=["set up a simulation study from geometry to outputs", "run a scenario in an open-source simulator and repeat it with several seeds", "carry out a sensitivity analysis and report percentiles", "combine macroscopic and microscopic models across scales"],
 narration_en="A simulation of a mass gathering is a chain of choices, and each link can break. First the geometry: walkable areas, walls, gates, stairs and ramps, from site plans and checked on site. Then demand: how many people, arriving when, going where, often from schedules and counts. Then the model: macroscopic for the whole network, microscopic for hot spots, calibrated as in Go 2. Then the runs: stochastic models give different answers with different random seeds, so run each scenario several times. Then sensitivity: vary the uncertain inputs, such as pre-movement times, walking speeds and compliance with schedules, and see how much the outputs change. Finally the outputs that answer your question, such as risk exposure or time to clear, reported with their spread. Open-source simulators make this transparent and reproducible. In this module you run a gate scenario in JuPedSim, a simulator from Forschungszentrum Jülich, repeat it with several seeds and gate widths, and add a simple sensitivity analysis. JuPedSim reproduces bottleneck flows of about one point one people per metre per second here, consistent with experiments.",
 narration_ar="محاكاة تجمع حاشد سلسلة من الخيارات، وكل حلقة فيها قد تنكسر. أولاً الهندسة: المناطق الصالحة للمشي، والجدران، والبوابات، والسلالم، والمنحدرات، من مخططات الموقع مع التحقق منها ميدانياً. ثم الطلب: كم عدد الناس، ومتى يصلون، وإلى أين يذهبون، وغالباً من الجداول والأعداد. ثم النموذج: عياني للشبكة كلها، ومجهري للنقاط الساخنة، معاير كما في المرحلة الثانية. ثم التشغيلات: تعطي النماذج العشوائية إجابات مختلفة مع بذور عشوائية مختلفة، فشغّل كل سيناريو عدة مرات. ثم الحساسية: غيّر المدخلات غير المؤكدة، كأزمنة ما قبل الحركة وسرعات المشي والالتزام بالجداول، وانظر كم تتغير المخرجات. وأخيراً المخرجات التي تجيب عن سؤالك، كالتعرض للخطر أو زمن الإخلاء، مع الإبلاغ عن مدى تفاوتها. وتجعل المحاكيات مفتوحة المصدر هذا شفافاً وقابلاً للتكرار. ستشغّل في هذه الوحدة سيناريو بوابة في JuPedSim، وهو محاكٍ من مركز يوليش للأبحاث، وتكرره بعدة بذور وعروض بوابات، وتضيف تحليل حساسية بسيطاً. ويعيد JuPedSim هنا إنتاج تدفقات عنق زجاجة تقارب شخصاً وعُشراً لكل متر في الثانية، بما يتفق مع التجارب.",
 diagram=dict(title="A simulation study, step by step", caption="Each step feeds the next; uncertainty enters at every step and must be carried through to the results.",
   nodes=[N("geo", "Geometry", "plans, checked on site", 110, 100, "space", "Walkable areas, obstacles, gates, ramps. Temporary structures (stalls, barriers, tents) matter."),
          N("dem", "Demand", "numbers, timing, destinations", 330, 100, "people", "From schedules, tickets, counts. Include profiles: speeds, groups, mobility."),
          N("mod", "Model", "macro + micro", 550, 100, "model", "Network or macro model for the whole site; micro model for hot spots; calibrated."),
          N("run", "Runs", "scenarios × seeds", 770, 100, "model", "Repeat stochastic runs; record outputs consistently."),
          N("sen", "Sensitivity", "vary uncertain inputs", 770, 300, "data", "One-at-a-time screening, then Monte Carlo or variance-based methods for key inputs."),
          N("out", "Outputs", "exposure, times, flows", 450, 300, "risk", "Answer the research question: risk exposure, time above thresholds, clearance times, with spread."),
          N("rep", "Reproducibility", "code, data, versions", 130, 300, "manage", "Share scripts, geometry and parameter files, simulator versions and seeds.")],
   edges=[E("geo", "dem"), E("dem", "mod"), E("mod", "run"), E("run", "sen"), E("sen", "out"), E("run", "out"), E("out", "rep", "documented")],
   tour=[T(["geo", "dem"], "Start with geometry and demand, checked against the real site.", [["geo", "dem"]]),
         T(["mod"], "Choose and calibrate a model, often macro for the network and micro for hot spots.", [["dem", "mod"]]),
         T(["run"], "Run every scenario with several random seeds.", [["mod", "run"]]),
         T(["sen", "out"], "Vary uncertain inputs, then report outputs with their spread.", [["run", "sen"], ["sen", "out"]]),
         T(["rep"], "Document everything so others can reproduce it.", [["out", "rep"]])]),
 sections=[
  S("Geometry and demand", "<p>Build the geometry from site plans, then <b>check it on site</b>: temporary stalls, barriers and vehicles change effective widths. Demand comes from schedules, ticketing and counts: how many, when, from where to where, and with what profile (speeds, groups, mobility). For the Hajj, group schedules and routes are key inputs.</p>",
    ("Inputs", "space", "Geometry and demand, checked.", [("Site plans + site visits", "Temporary obstacles."), ("Schedules and counts", "Who, when, where."), ("Profiles", "Speeds, groups, mobility.")])),
  S("Running a scenario in JuPedSim", "<p>JuPedSim is an open-source simulator with a Python interface (<code>pip install jupedsim</code>). The lab builds a 20 m × 10 m forecourt emptying through a gate, places 150 people with the collision-free speed model, and repeats each gate width with 5 seeds. Results: 1.0 m gate about 143 s, 1.6 m about 80 s, 2.4 m about 57 s, with flows of about 1.05 to 1.18 people per metre per second, consistent with experiments.</p>",
    ("JuPedSim", "model", "Open, scriptable, reproducible.", [("pip install jupedsim", "Python interface."), ("1.0 / 1.6 / 2.4 m", "143 / 80 / 57 s."), ("1.05–1.18 per m per s", "Matches experiments.")])),
  S("Seeds and sensitivity", "<p>Stochastic models differ between runs: report the <b>mean and spread</b> over seeds. Then vary uncertain inputs. In the explorer, ± 50% uncertainty in pre-movement and ± 20% in specific flow spread the egress time widely; the 95th percentile, not the median, is what safety depends on. Screen inputs one at a time first, then study the important ones jointly.</p>",
    ("Sensitivity", "data", "Seeds and uncertain inputs.", [("Mean and spread", "Over seeds."), ("Vary inputs", "Pre-movement, flow, compliance."), ("95th percentile", "For safety.")])),
  S("Across scales", "<p>No single model fits a whole mass gathering. A common approach couples a fast <b>network or macroscopic model</b> for the whole site and timetable with <b>microscopic models</b> for critical spots such as ramps, junctions and gates. The coupling passes flows and densities at the boundaries. Check that both models agree where they overlap.</p>",
    ("Multi-scale", "model", "Macro for the site, micro for hot spots.", [("Network model", "Whole site and timetable."), ("Micro at hot spots", "Ramps, gates."), ("Check overlaps", "Both should agree.")])),
 ],
 callouts=[C(1, "try", "Run it yourself", "<p>Download the JuPedSim script, install JuPedSim, and add a 3.2 m gate. Is the flow per metre still about the same?</p>"),
           C(2, "trap", "One run is an anecdote", "<p>A single stochastic run can be unusually good or bad. Never report one run as the result.</p>")],
 explorer=dict(widget="sensitivity", intro="3,000 people leave through 8 m of exits. Change the uncertainty in pre-movement time and specific flow.", predict="Which uncertainty spreads the egress time more: pre-movement or flow?"),
 code=[dict(title="A gate scenario in JuPedSim", lang="python", file="labs/go3/m36_jupedsim.py", runnable=False, explain="Requires pip install jupedsim (version 1.x). Builds the geometry with shapely, runs the collision-free speed model, repeats each gate width with 5 seeds.", expected="gate 1.0 m: evacuation 142.7 s (min 141.2, max 143.9), flow 1.05 per m per s\ngate 1.6 m: evacuation 79.5 s (min 78.2, max 80.3), flow 1.18 per m per s\ngate 2.4 m: evacuation 57.3 s (min 55.5, max 59.1), flow 1.09 per m per s"),
       dict(title="Monte Carlo sensitivity of egress time", lang="python", runnable=True, source="import numpy as np\nrng = np.random.default_rng(21)\nN, width = 3000, 8.0\nfor pu, fu in [(0.0, 0.0), (0.5, 0.0), (0.0, 0.2), (0.5, 0.2)]:\n    pre = 120 * (1 + rng.uniform(-pu, pu, 5000))\n    js = 1.3 * (1 + rng.uniform(-fu, fu, 5000))\n    t = pre + N / (js * width)\n    p5, p50, p95 = np.percentile(t, [5, 50, 95]) / 60\n    print(f'pre +/-{pu:.0%}, flow +/-{fu:.0%}: median {p50:.1f} min, 5-95% {p5:.1f}-{p95:.1f} min')",
   explain="One-at-a-time and joint uncertainty. Which input widens the interval more?", expected="pre +/-0%, flow +/-0%: median 6.8 min, 5-95% 6.8-6.8 min\n...")],
 takeaways=["A simulation study chains geometry, demand, model, runs, sensitivity and outputs.", "Check geometry on site; derive demand from schedules and counts.", "Repeat stochastic runs and vary uncertain inputs; report percentiles.", "Couple macro models for the site with micro models for hot spots; share code and data."],
 quiz=[Q("Why run each scenario with several seeds?", ["To use more computer time", "Stochastic models vary between runs; report the spread", "Seeds make it faster", "It is required by JuPedSim"], 1, "One run is an anecdote."),
       Q("In the JuPedSim lab, a 1.6 m gate gave a flow of about…", ["0.5 per m per s", "1.2 per m per s", "3 per m per s", "8 per m per s"], 1, "About 1.18, consistent with experiments."),
       Q("A common multi-scale approach couples…", ["Two identical micro models", "A network or macro model for the site with micro models at hot spots", "Weather and traffic models", "Only hand calculations"], 1, "Macro for scale, micro for detail."),
       Q("Which percentile matters most for safety?", ["5th", "Median", "95th or higher", "None"], 2, "The slow tail.")],
 glossary=[G("Random seed", "A number that fixes the random sequence of a stochastic simulation run."), G("Sensitivity analysis", "Studying how outputs change with uncertain inputs."), G("JuPedSim", "Open-source pedestrian simulator from Forschungszentrum Jülich, with a Python interface."), G("Multi-scale coupling", "Linking models of different detail at their boundaries."), G("Reproducibility", "The ability of others to rerun a study and get the same results.")],
 resources=[RS("JuPedSim", "https://www.jupedsim.org/", "Documentation and tutorials for the open-source simulator."),
            RS("Vadere", "https://www.vadere.org/", "Another open framework, with optimal steps and other models."),
            RS("Ronchi et al. (2013): V&V of evacuation models (NIST TN 1822)", "https://nvlpubs.nist.gov/nistpubs/TechnicalNotes/NIST.TN.1822.pdf", "Testing and reporting simulation results.")],
 palace=("Model tent", "In the model tent, a sand table holds a tiny copy of the route; dice roll on it again and again, each throw a seed, while an assistant chalks the 95th percentile on a blackboard and files the code in a labelled box."),
 qb=[("Recall", "List the main steps of a crowd simulation study.", "Geometry, demand, model choice and calibration, runs with several seeds, sensitivity analysis, outputs with spread, and documentation.", "A chain where every link matters.", "A recipe from ingredients to plating."),
     ("Explain", "Why check geometry on site?", "Temporary stalls, barriers, vehicles and closures change effective widths and routes, so plans alone can overestimate capacity.", "The map is not the territory.", "A floor plan without the furniture."),
     ("Recall", "What flows did the JuPedSim gate lab give?", "About 1.05 to 1.18 people per metre per second, consistent with laboratory experiments.", "A calibrated model should match data.", "Just over one person per metre per second."),
     ("Explain", "What is the purpose of a sensitivity analysis?", "To see how much outputs change with uncertain inputs, identify which inputs matter most, and report results with honest ranges.", "Find what drives the answer.", "Wiggling each knob to see which moves the needle."),
     ("Apply", "Why couple a macroscopic model with microscopic ones for the Hajj?", "The whole site and timetable need a fast network model, but ramps, junctions and gates need individual detail; coupling gives both.", "Scale and detail together.", "A city map with zoomed-in inserts."),
     ("Apply", "What would you share to make a simulation study reproducible?", "Scripts, geometry and parameter files, input data (or how to get it), simulator versions and random seeds.", "Enough for someone else to rerun it.", "A recipe with exact quantities and oven settings.")]))
M.append(dict(id="3.7", go=3, slug="interventions-and-evaluation", title="Interventions and their evaluation", minutes=45, tag="Interventions", systems=["manage", "space"],
 summary="Metering, one-way systems, holding areas, scheduling and information can keep density down, but they move risk as well as reduce it. Evaluate them with simulation and data, including side effects.",
 outcomes=["describe common crowd interventions and how they work", "show with a model how metering moves waiting from one place to another", "design an evaluation of an intervention with a fair comparison", "look for unintended effects"],
 narration_en="Once you understand where risk builds up, you can change the system. The most common tools are simple. Metering limits the rate at which people enter a space, so waiting happens in a safer place, often an open approach rather than an enclosed plaza. One-way systems separate opposing flows, as on the rebuilt Jamarat Bridge. Holding areas store people safely and release them in batches. Scheduling spreads arrivals over time. Information tells people where to go and when, and stewards make it real. But interventions do not make risk disappear; they move it. Metering creates a queue outside, which must itself be safe. A one-way system lengthens some routes. A holding area can become a crush if it is not released in time. That is why every intervention needs an evaluation: compare it fairly with a baseline, in simulation first and with data after, and look for unintended effects. In this module you will meter the gates in front of a plaza and see density inside fall while the queue outside grows.",
 narration_ar="ما إن تفهم أين يتراكم الخطر حتى تستطيع تغيير النظام. وأكثر الأدوات شيوعاً بسيطة. فالتحكم في معدل الدخول يحدّ من سرعة دخول الناس إلى مكان ما، فيحدث الانتظار في مكان أكثر أماناً، غالباً في طريق مفتوح بدلاً من ساحة مغلقة. وأنظمة الاتجاه الواحد تفصل التدفقات المتعاكسة، كما في جسر الجمرات الجديد. ومناطق الانتظار تحفظ الناس بأمان وتطلقهم على دفعات. والجدولة توزّع الوصول عبر الزمن. والمعلومات تخبر الناس إلى أين يذهبون ومتى، والمنظّمون يجعلونها واقعاً. لكن التدخلات لا تُخفي الخطر؛ بل تنقله. فالتحكم في معدل الدخول يصنع طابوراً في الخارج يجب أن يكون هو نفسه آمناً. ونظام الاتجاه الواحد يطيل بعض الطرق. ومنطقة الانتظار قد تصبح موقع تزاحم إن لم تُطلق في الوقت المناسب. ولهذا يحتاج كل تدخل إلى تقييم: قارنه مقارنة عادلة بخط أساس، بالمحاكاة أولاً وبالبيانات بعد ذلك، وابحث عن الآثار غير المقصودة. ستتحكم في هذه الوحدة في معدل الدخول عند بوابات أمام ساحة، وترى الكثافة في الداخل تنخفض بينما يكبر الطابور في الخارج.",
 diagram=dict(title="Interventions move risk as well as reduce it", caption="Each tool lowers density somewhere; evaluation checks where the waiting went and whether that place is safe.",
   nodes=[N("met", "Metering", "limit inflow rate", 130, 100, "manage", "Gates or stewards admit people at a set rate; waiting moves upstream."),
          N("one", "One-way systems", "separate opposing flows", 130, 260, "space", "Separate routes in and out; no head-on conflicts in narrow spaces."),
          N("hold", "Holding areas", "store and release", 130, 420, "space", "Pens or zones where people wait safely and are released in batches."),
          N("sch", "Scheduling and information", "spread demand", 450, 420, "people", "Time slots, staggered starts, real-time information and stewards."),
          N("den", "Density at the hot spot", "goes down", 450, 180, "risk", "The intended effect."),
          N("side", "Side effects", "queues elsewhere, longer routes", 770, 100, "risk", "Waiting moves upstream; routes lengthen; holding areas can become hot spots themselves."),
          N("eval", "Evaluation", "baseline, simulation, data", 770, 320, "data", "Fair comparison, sensitivity analysis, monitoring after implementation.")],
   edges=[E("met", "den"), E("one", "den"), E("hold", "den"), E("sch", "den"), E("met", "side", "moves queue"), E("hold", "side", "if not released"), E("den", "eval"), E("side", "eval")],
   tour=[T(["met", "one", "hold", "sch"], "Four families of tools: metering, one-way systems, holding areas, scheduling and information."),
         T(["den"], "All aim to keep density down at the hot spot.", [["met", "den"], ["one", "den"], ["hold", "den"], ["sch", "den"]]),
         T(["side"], "But they move risk: queues upstream, longer routes, new hot spots.", [["met", "side"], ["hold", "side"]]),
         T(["eval"], "So evaluate both the intended effect and the side effects.", [["den", "eval"], ["side", "eval"]])]),
 sections=[
  S("The toolbox", "<p><b>Metering</b>: admit people at a controlled rate. <b>One-way systems</b>: separate opposing flows. <b>Holding areas</b>: store and release in batches. <b>Scheduling</b>: spread demand over time. <b>Information and stewarding</b>: guide choices and enforce plans. <b>Design changes</b>: widen bottlenecks, remove obstacles, add routes. Most real plans combine several.</p>",
    ("Toolbox", "manage", "Six families of interventions.", [("Metering and holding", "Control the rate."), ("One-way and design", "Change the space."), ("Scheduling and information", "Change the timing and choices.")])),
  S("Metering moves the queue", "<p>A 1,200 m² plaza feeds a venue at 180 people per minute, with arrivals peaking at 320 per minute. Without metering the plaza peaks at about 2.5 per m². Metering the gates at 200 per minute keeps it under 1 per m², but a queue of over 2,000 builds outside (lab, 20 random seeds). Metering is only an improvement if the space outside is open, wide and managed.</p>",
    ("Metering", "risk", "Inside down, outside up.", [("No metering: 2.5 per m²", "Plaza peak."), ("200 per min: under 1 per m²", "Plaza peak."), ("Queue outside: over 2,000", "Must be safe.")])),
  S("Evaluating fairly", "<p>Compare the intervention with a <b>baseline</b> under the same demand, using the same model and outputs, over several seeds and sensitivity cases. Report <b>where risk exposure goes</b>, not only whether it falls at the target. After implementation, monitor with data and compare with predictions. Real-world before–after comparisons must allow for other changes, such as different attendance.</p>",
    ("Evaluate", "data", "Same demand, same outputs, both places.", [("Baseline", "Same demand and model."), ("Where risk goes", "Exposure everywhere."), ("After implementation", "Monitor and compare.")])),
  S("Unintended effects", "<p>Look for: queues in unsafe places; longer routes that people refuse to follow (short-cuts through barriers); holding areas that fill faster than planned; counterflows created by people going back for friends; and information overload. People adapt to interventions, so simulate behavioural responses (for example non-compliance) as part of the sensitivity analysis.</p>",
    ("Side effects", "risk", "People adapt.", [("Unsafe queues", "Outside the gate."), ("Short-cuts", "Around barriers."), ("Non-compliance", "Include it in tests.")])),
 ],
 callouts=[C(1, "try", "Explore it", "<p>Find the metering rate that keeps the plaza below 2 per m² with the smallest queue outside.</p>"),
           C(3, "research", "Research angle", "<p>Few interventions at mass gatherings have been evaluated with before–after data. Designing such evaluations is a valuable research contribution.</p>")],
 explorer=dict(widget="metering", intro="Meter the gates in front of a 1,200 m² plaza and watch density inside and the queue outside.", predict="If you meter more strictly, does the total waiting disappear, or move?"),
 code=[dict(title="Gate metering with random arrivals", lang="python", file="labs/go3/m37_metering.py", runnable=True, explain="Sweeps the metering rate with 20 random seeds each and reports the plaza's peak density and the queue outside.", expected="metering 400/min: plaza peak 2.47 per m2, queue outside 0\n...\nmetering 200/min: plaza peak 0.86 per m2, queue outside 2,330")],
 takeaways=["Interventions: metering, one-way systems, holding areas, scheduling, information, design changes.", "Interventions move risk as well as reduce it; metering moves waiting upstream.", "Evaluate against a fair baseline and report where risk exposure goes.", "Include people's adaptation, such as non-compliance and short-cuts, in tests."],
 quiz=[Q("Metering the gates of a plaza mainly…", ["Removes all waiting", "Moves waiting from the plaza to the approach", "Raises density inside", "Has no effect"], 1, "The queue moves upstream."),
       Q("A fair evaluation compares the intervention with…", ["A different event", "A baseline under the same demand and outputs", "Nothing", "Last year's weather"], 1, "Like with like."),
       Q("Which is an unintended effect of barriers?", ["Shorter routes", "People taking short-cuts around them", "Lower attendance", "Faster walking"], 1, "People adapt."),
       Q("In the lab, metering at 200 per minute gave a plaza peak of about…", ["2.5 per m²", "under 1 per m²", "5 per m²", "0"], 1, "About 0.86 per m².")],
 glossary=[G("Metering", "Admitting people to a space at a controlled rate."), G("Holding area", "A space where people wait safely before release."), G("One-way system", "Routing that separates opposing flows."), G("Baseline", "The situation without the intervention, used for comparison."), G("Unintended effect", "A consequence of an intervention that was not its purpose.")],
 resources=[RS("HSE: Managing crowds safely", "https://www.hse.gov.uk/pubns/books/hsg154.htm", "Practical crowd control measures and planning."),
            RS("Johansson et al. (2008)", "https://arxiv.org/abs/0810.4590", "Interventions at the Jamarat after 2006."),
            RS("Still et al. (2020)", "https://e-space.mmu.ac.uk/625559/", "Case studies of crowd safety interventions.")],
 palace=("Waiting square", "At the waiting square, a gatekeeper turns a tap that drips people into a fenced plaza; outside, the queue coils like a garden hose on an open field, and a referee compares two scoreboards labelled BEFORE and AFTER."),
 qb=[("Recall", "Name four types of crowd intervention.", "Metering, one-way systems, holding areas, scheduling, information and stewarding, design changes.", "Rate, space, time and information.", "A tap, a one-way sign, a pen and a clock."),
     ("Explain", "Why do interventions move risk rather than delete it?", "Because demand still has to go somewhere: metering creates queues upstream, holding areas store people, one-way systems lengthen routes; the new places must be safe.", "Conservation of people.", "Squeezing a balloon: the air moves."),
     ("Calculate", "Arrivals peak at 320 per minute, venue takes 180, metering at 200. Roughly how fast does the outside queue grow at the peak?", "About 320 − 200 = 120 people per minute.", "Inflow minus metered rate.", "A bath filling at 120 cups a minute."),
     ("Explain", "What makes an evaluation fair?", "Same demand, same model and outputs, several seeds and sensitivity cases, comparing intervention and baseline, and reporting exposure in all places.", "Like with like.", "Two runners on the same track."),
     ("Apply", "Name two unintended effects to test for when adding barriers.", "People taking short-cuts around them, new bottlenecks at barrier ends, longer routes that cause counterflows, and holding areas filling too fast.", "People adapt.", "Water finding a way around a dam."),
     ("Apply", "When is metering a good idea?", "When the space upstream is open, wide and managed, so waiting there is safer than in the enclosed space downstream.", "Move waiting to safer ground.", "Queue in the park, not in the corridor.")]))
M.append(dict(id="3.8", go=3, slug="research-frontier", title="The research frontier and writing it up", minutes=40, tag="Research", systems=["people", "data"],
 summary="Open questions remain: pushing and high-density physics, the psychology of crowds, AI for monitoring, digital twins, and heat and health at mass gatherings. Report findings honestly, with uncertainty and limits.",
 outcomes=["name open research questions in crowd dynamics and mass-gathering safety", "describe how physics and social psychology are being combined", "write a results section that states uncertainty and limits", "plan how to communicate findings to decision makers"],
 narration_en="Crowd science has come a long way since Fruin's levels of service, but many questions remain open. How exactly do pushing and contact forces spread through very dense crowds, and what densities and forces are truly critical? Laboratory experiments on pushing at entrances, and new sensors that measure body forces, are starting to answer this. How do social identity, culture and norms change movement, and how can models include them? Research increasingly combines pedestrian physics with social psychology. Can artificial intelligence count and track crowds reliably in real time, across cameras and cultures, while protecting privacy? Can digital twins of venues forecast danger early enough to act? How do heat and health interact with crowding at events such as the Hajj, where many participants are older? When you write up your own study, be honest about uncertainty and limits: what your data and model can and cannot show, and how sensitive your conclusions are. Decision makers need clear messages, ranges rather than single numbers, and a plain statement of what would change your conclusions.",
 narration_ar="قطع علم الحشود شوطاً طويلاً منذ مستويات الخدمة لفروين، لكن أسئلة كثيرة ما زالت مفتوحة. كيف تنتشر قوى الدفع والتلامس بالضبط عبر الحشود الكثيفة جداً، وما الكثافات والقوى الحرجة حقاً؟ بدأت التجارب المخبرية على التدافع عند المداخل، وأجهزة الاستشعار الجديدة التي تقيس القوى على الأجساد، تجيب عن ذلك. وكيف تغيّر الهوية الاجتماعية والثقافة والأعراف الحركة، وكيف يمكن للنماذج أن تتضمنها؟ إذ تجمع الأبحاث بشكل متزايد بين فيزياء المشاة وعلم النفس الاجتماعي. وهل يستطيع الذكاء الاصطناعي عدّ الحشود وتتبعها بموثوقية في الزمن الحقيقي، عبر الكاميرات والثقافات، مع حماية الخصوصية؟ وهل تستطيع التوائم الرقمية للأماكن التنبؤ بالخطر مبكراً بما يكفي للتصرف؟ وكيف تتفاعل الحرارة والصحة مع الازدحام في فعاليات كالحج، حيث كثير من المشاركين كبار في السن؟ وعندما تكتب دراستك، كن صادقاً بشأن عدم اليقين والحدود: ما الذي تستطيع بياناتك ونموذجك إظهاره وما لا تستطيع، ومدى حساسية استنتاجاتك. فصنّاع القرار يحتاجون إلى رسائل واضحة، ونطاقات بدلاً من أرقام مفردة، وبياناً صريحاً لما قد يغيّر استنتاجاتك.",
 diagram=dict(title="Open questions around a crowd study", caption="Five research fronts, and the reporting that turns a study into something decision makers can use.",
   nodes=[N("push", "Pushing and forces", "what is truly critical?", 130, 100, "risk", "Experiments on pushing at entrances and force sensors on bodies; how forces spread at extreme density."),
          N("psy", "Psychology and culture", "identity, norms", 130, 260, "people", "Social identity, groups, culture and norms in movement models (Sieben et al. 2017; Drury et al. 2009)."),
          N("ai", "AI for monitoring", "counting, tracking, privacy", 130, 420, "data", "Reliable real-time counting and tracking across cameras and cultures, with privacy protection."),
          N("twin", "Digital twins", "forecast early", 450, 420, "model", "Models in step with live data, forecasting danger minutes ahead."),
          N("heat", "Heat and health", "vulnerable crowds", 770, 420, "people", "Interactions of heat, age, health and crowding at mass gatherings such as the Hajj."),
          N("study", "Your study", "question, data, model", 450, 210, "model", "Your research question, built in modules 3.1 to 3.7."),
          N("rep", "Reporting", "uncertainty and limits", 770, 210, "manage", "Ranges, sensitivity, model limits, and a clear message for decision makers.")],
   edges=[E("push", "study"), E("psy", "study"), E("ai", "study"), E("twin", "study"), E("heat", "study"), E("study", "rep", "write up")],
   tour=[T(["push", "psy"], "Two fronts: the physics of pushing and forces, and the psychology of crowds."),
         T(["ai", "twin"], "Two more: AI for monitoring, and digital twins that forecast."),
         T(["heat"], "And heat and health at mass gatherings."),
         T(["study"], "Your study draws on these fronts.", [["push", "study"], ["psy", "study"], ["ai", "study"], ["twin", "study"], ["heat", "study"]]),
         T(["rep"], "Finally, report it honestly, with uncertainty and limits.", [["study", "rep"]])]),
 sections=[
  S("Physics at extreme density", "<p>Most models were developed and calibrated at moderate densities. At extreme densities, contact forces, pushing and falls dominate. Laboratory experiments with pushing at entrances, and pressure sensors worn by participants, are beginning to quantify how forces spread. Key questions: which densities and forces are critical, and how do falls start and spread?</p>",
    ("Extreme density", "risk", "Forces, pushing, falls.", [("Pushing experiments", "At entrances."), ("Force sensors", "On bodies."), ("Falls", "How collapses start.")])),
  S("Crowds are social", "<p>Pedestrian dynamics increasingly works with social psychology. Sieben, Schumann and Seyfried (2017) showed how social norms and identity change behaviour in experiments; Drury and colleagues showed cooperation in emergencies. Open questions: how to represent groups, culture and shared identity in models, and how to calibrate them.</p>",
    ("Social crowds", "people", "Physics meets psychology.", [("Norms and identity", "Sieben et al. 2017."), ("Cooperation", "Drury et al. 2009."), ("In models", "Groups and culture.")])),
  S("AI, digital twins and health", "<p>Deep learning has made crowd counting from images practical, but reliability across cameras, crowds and conditions, and privacy, remain open. Digital twins promise forecasts that extend lead time, but need validated models and good data. At the Hajj and other events in hot climates, heat and health interact with crowding and walking speeds, a frontier where crowd science meets mass-gathering medicine.</p>",
    ("New tools", "data", "AI, twins, health.", [("Reliable AI counting", "Across conditions."), ("Digital twins", "Forecasting."), ("Heat and health", "Mass-gathering medicine.")])),
  S("Writing it up", "<p>A strong results section states: the question; the data and model, with calibration and validation; the scenarios; results <b>with ranges</b> (seeds and sensitivity); what the model <b>cannot</b> represent and how that could bias results; and a clear message for decision makers. Avoid false precision (\"egress time 6.83 min\") and over-claiming (\"proves the site is safe\").</p>",
    ("Write-up", "manage", "Honest, clear, useful.", [("Ranges, not points", "Seeds and sensitivity."), ("Limits stated", "What the model cannot see."), ("Clear message", "For decision makers.")])),
 ],
 callouts=[C(3, "trap", "Over-claiming", "<p>A simulation cannot prove a site is safe. It can show that, under stated assumptions, a design keeps risk exposure below a threshold with a stated margin.</p>"),
           C(1, "research", "Pick your front", "<p>Choose one front for your project, and say in your proposal which open question you address and how your data could answer it.</p>")],
 code=[dict(title="Reporting results with ranges", lang="python", runnable=True, source="import numpy as np\nrng = np.random.default_rng(3)\n# exposure (person-minutes above 4 per m2) from 20 seeds for two scenarios\nbase = rng.normal(95000, 12000, 20)\nmeter = rng.normal(61000, 15000, 20)\nfor name, x in [('baseline', base), ('metering', meter)]:\n    lo, hi = np.percentile(x, [5, 95])\n    print(f'{name:9s}: median {np.median(x):,.0f}, 90% range {lo:,.0f}-{hi:,.0f} person-minutes')\nd = base - meter\nprint(f'reduction: median {np.median(d):,.0f}; in {np.mean(d > 0):.0%} of paired runs metering was better')",
   explain="Report medians and ranges, and how often one scenario beats the other, instead of a single number.", expected="baseline : median 91,881, 90% range 70,439-120,260 person-minutes\nmetering : median 61,868, 90% range 35,101-84,479 person-minutes\nreduction: median 31,076; in 90% of paired runs metering was better")],
 takeaways=["Open fronts: physics at extreme density, crowd psychology, AI monitoring, digital twins, heat and health.", "Pedestrian dynamics increasingly combines physics with social psychology.", "Report results with ranges, state model limits, avoid false precision.", "Give decision makers a clear message and say what would change it."],
 quiz=[Q("Why is extreme density a research frontier?", ["It never happens", "Most models were calibrated at moderate densities; forces and falls dominate at extreme ones", "Cameras cannot see it", "It is illegal to study"], 1, "Physics changes at extreme density."),
       Q("Which is good reporting practice?", ["One run, three decimals", "Medians and ranges over seeds and sensitivity cases", "Hiding limits", "Claiming proof of safety"], 1, "Ranges, not points."),
       Q("Combining physics with social psychology means…", ["Ignoring groups", "Representing norms, identity and groups in crowd models", "Only using surveys", "Only using forces"], 1, "Crowds are social."),
       Q("A simulation can…", ["Prove a site is safe", "Show that, under stated assumptions, risk stays below a threshold with a margin", "Replace stewards", "Predict exact attendance"], 1, "Conditional, not absolute.")],
 glossary=[G("False precision", "Reporting more digits than the uncertainty justifies."), G("Over-claiming", "Stating conclusions stronger than the evidence supports."), G("Social norm", "A shared expectation about how to behave."), G("Mass-gathering medicine", "The field studying health risks and care at mass gatherings.")],
 resources=[RS("Sieben, Schumann and Seyfried (2017): Collective phenomena in crowds", "https://doi.org/10.1371/journal.pone.0177328", "Where pedestrian dynamics needs social psychology."),
            RS("Haghani and Sarvi (2018): Crowd behaviour and motion", "https://doi.org/10.1016/j.trb.2017.06.017", "Review of empirical methods and open questions."),
            RS("Memish et al. (2012): Lessons from the Hajj", "https://doi.org/10.1016/S1473-3099(11)70337-1", "Mass-gathering medicine.")],
 palace=("Farewell gate", "At the farewell gate, five signposts point to unexplored valleys labelled PUSHING, PSYCHOLOGY, AI, TWINS and HEAT; a scribe at a lectern writes a report in which every number carries a little pair of brackets for its range."),
 qb=[("Recall", "Name three open research fronts in crowd dynamics.", "Pushing and forces at extreme density; social psychology and culture in models; AI for monitoring; digital twins; heat and health at mass gatherings.", "Physics, people, technology, health.", "Five signposts at a crossroads."),
     ("Explain", "Why is combining physics and social psychology important?", "Crowd movement depends on norms, identity and groups as well as space and forces; models that ignore them can mispredict behaviour, especially in emergencies.", "Crowds are social systems.", "A football crowd and a choir move differently in the same hall."),
     ("Explain", "What is false precision and how do you avoid it?", "Reporting more digits than the uncertainty supports; report rounded values with ranges from seeds and sensitivity.", "Precision must match uncertainty.", "Measuring a cloud with a micrometre."),
     ("Apply", "What should a results section say about model limits?", "What the model cannot represent (for example pushing, groups or information), how that could bias the results, and which assumptions would change the conclusions.", "Honesty builds trust.", "A map that marks the areas it has not surveyed."),
     ("Explain", "Why can a simulation not prove a site is safe?", "Results depend on assumptions about demand, behaviour and parameters; a simulation can only show conditional performance under stated assumptions and margins.", "Models are conditional.", "A weather model cannot promise sunshine."),
     ("Apply", "How would you communicate a finding to an event authority?", "A clear message, ranges rather than single numbers, the key assumptions, what would change the conclusion, and practical implications.", "Clear, honest, actionable.", "A one-page brief with a traffic-light summary.")]))
